function validate([nums1, nums2, k1, k2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2) || nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 1 || nums1.length > 100000) return 'The arrays need 1 to 10^5 values.';
  if (![...nums1, ...nums2].every(v => Number.isInteger(v) && v >= 0 && v <= 100000)) return 'Every value is an integer from 0 to 10^5.';
  if (![k1, k2].every(k => Number.isInteger(k) && k >= 0 && k <= 1000000000)) return 'k1 and k2 are integers from 0 to 10^9.';
  return null;
}

