function minSumSquareDiff(nums1, nums2, k1, k2) {
  const diffs = nums1.map((value, i) => Math.abs(value - nums2[i]));
  diffs.sort((a, b) => b - a);
  diffs.push(0);
  let moves = k1 + k2;
  let level = diffs[0];
  let width = 1;

  while (width < diffs.length) {
    const cost = (level - diffs[width]) * width;
    if (cost > moves) {
      break;
    }
    moves -= cost;
    level = diffs[width];
    width++;
  }
  if (level === 0) {
    return 0;
  }

  level -= Math.floor(moves / width);
  const lowered = moves % width;
  let total = lowered * (level - 1) ** 2 + (width - lowered) * level ** 2;
  for (let i = width; i < diffs.length; i++) {
    total += diffs[i] ** 2;
  }
  return total;
}

