function minSumSquareDiff(nums1, nums2, k1, k2) {
  const gaps = [];
  let sum = 0;
  for (let i = 0; i < nums1.length; i++) {
    gaps.push(Math.abs(nums1[i] - nums2[i]));
    sum += gaps[i];
  }
  // Each move shrinks the currently largest gap by one; more moves than the total gap are wasted.
  let left = Math.min(k1 + k2, sum);
  while (left > 0) {
    let top = 0;
    for (let i = 1; i < gaps.length; i++) if (gaps[i] > gaps[top]) top = i;
    gaps[top]--;
    left--;
  }
  return gaps.reduce((acc, g) => acc + g * g, 0);
}

