function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 7);
    const top = [0, 1, 3, 10, 30][int(0, 4)];
    const nums1 = Array.from({ length: n }, () => int(0, top));
    const nums2 = Array.from({ length: n }, () => rand() < 0.2 ? nums1[0] : int(0, top));
    return [nums1, nums2, int(0, 12), int(0, 12)];
  }
  const n = 2000;
  const top = [100, 1000, 100000][int(0, 2)];
  const nums1 = Array.from({ length: n }, () => int(0, top));
  const nums2 = Array.from({ length: n }, () => int(0, top));
  let sum = 0;
  for (let i = 0; i < n; i++) sum += Math.abs(nums1[i] - nums2[i]);
  if (rand() < 0.15) return [nums1, nums2, 1000000000, int(0, 1000000000)];
  const budget = Math.floor(rand() * sum);
  const k1 = Math.min(1000000000, Math.floor(budget * rand()));
  return [nums1, nums2, k1, Math.min(1000000000, budget - k1)];
}
